`,solutionCode:`// A kernel runs once per output cell — 64 cells here, 64 threads.
const gpu = new GPU({ mode });

const double = gpu.createKernel(function (data) {
  return data[this.thread.x] * 2;
}, { output: [64] });

const result = double(data);
console.log(result);
