    <g fill="none" stroke="var(--line)">
      <rect x="62" y="18" width="24" height="16" rx="3"/><rect x="112" y="36" width="24" height="16" rx="3"/><rect x="112" y="86" width="24" height="16" rx="3"/>
    </g>
